def post_review(payload, state):
    draft = research_agent(payload['question'])
    checked = review_agent(draft)
    return {'reply': checked}

@app.post('/chat')
def chat():
    messages = get_session_history()
    messages.append({'role': 'user', 'content': request.json['message']})
    try:
        reply = run_agent(messages, conversation_id=session.get('sid'))
    except Exception:
        messages.pop()
        return {'error': 'turn failed'}, 502
    messages.append({'role': 'assistant', 'content': reply})
    return {'reply': reply}

@app.get('/health')
def health():
    return {'ok': True}

@app.post('/reset')
def reset():
    clear_history()
    return {'ok': True}

FlaskInstrumentor().instrument_app(app)
